-- +goose Up
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,full_name text NOT NULL,role text NOT NULL CHECK(role IN ('admin','staff','reporter')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid REFERENCES business_units(id),name text NOT NULL);
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),parent_id uuid REFERENCES locations(id),name text NOT NULL,unit_id uuid REFERENCES business_units(id));
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('machine','equipment','vehicle','land','building')));
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inventory_no text NOT NULL UNIQUE,name text NOT NULL,category_id uuid NOT NULL REFERENCES categories(id),unit_id uuid NOT NULL REFERENCES business_units(id),department_id uuid REFERENCES departments(id),location_id uuid REFERENCES locations(id),assigned_user_id uuid REFERENCES users(id),condition text NOT NULL DEFAULT 'baik',usage_status text NOT NULL DEFAULT 'aktif',purchase_cost numeric(18,2),acquired_on date,warranty_until date,specifications jsonb NOT NULL DEFAULT '{}',archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_search_idx ON assets(inventory_no,name);CREATE INDEX assets_location_idx ON assets(location_id) WHERE archived_at IS NULL;
CREATE TABLE lands(asset_id uuid PRIMARY KEY REFERENCES assets(id),area_m2 numeric(18,2) NOT NULL CHECK(area_m2>0),title_type text,title_no text,title_expiry date);
CREATE TABLE buildings(asset_id uuid PRIMARY KEY REFERENCES assets(id),land_asset_id uuid REFERENCES lands(asset_id),area_m2 numeric(18,2) NOT NULL CHECK(area_m2>0),floors int CHECK(floors>0));
CREATE TABLE vehicles(asset_id uuid PRIMARY KEY REFERENCES assets(id),plate_no text NOT NULL UNIQUE,vin text UNIQUE,engine_no text UNIQUE,odometer_km bigint NOT NULL DEFAULT 0,annual_due date,five_year_due date);
CREATE TABLE vehicle_renewals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES vehicles(asset_id),kind text NOT NULL CHECK(kind IN ('annual','five_year')),old_due date,new_due date NOT NULL,cost numeric(18,2),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES assets(id),from_location_id uuid REFERENCES locations(id),to_location_id uuid REFERENCES locations(id),from_department_id uuid REFERENCES departments(id),to_department_id uuid REFERENCES departments(id),reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE damage_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),asset_id uuid REFERENCES assets(id),location_text text NOT NULL,description text NOT NULL,urgency text NOT NULL CHECK(urgency IN ('rendah','sedang','tinggi')),status text NOT NULL DEFAULT 'baru',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE maintenance_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES assets(id),title text NOT NULL,interval_days int CHECK(interval_days>0),next_due date NOT NULL,checklist jsonb NOT NULL DEFAULT '[]',active boolean NOT NULL DEFAULT true);
CREATE TABLE work_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES assets(id),plan_id uuid REFERENCES maintenance_plans(id),report_id uuid UNIQUE REFERENCES damage_reports(id),occurrence_key text UNIQUE,status text NOT NULL DEFAULT 'terjadwal',assignee_id uuid REFERENCES users(id),diagnosis text,action_taken text,checklist jsonb NOT NULL DEFAULT '[]',estimated_cost numeric(18,2),actual_cost numeric(18,2),due_on date,created_at timestamptz NOT NULL DEFAULT now(),CHECK ((plan_id IS NOT NULL) <> (report_id IS NOT NULL)));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text,title text NOT NULL,category text NOT NULL,sensitivity text NOT NULL DEFAULT 'internal',expires_on date,physical_location text,pic_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES documents(id),version_no int NOT NULL,storage_key text NOT NULL,filename text NOT NULL,mime_type text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,uploaded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,version_no));
CREATE TABLE asset_documents(asset_id uuid NOT NULL REFERENCES assets(id),document_id uuid NOT NULL REFERENCES documents(id),PRIMARY KEY(asset_id,document_id));
CREATE TABLE depreciation_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid NOT NULL REFERENCES categories(id),book text NOT NULL DEFAULT 'commercial',version int NOT NULL,method text NOT NULL CHECK(method IN ('straight_line','declining','double_declining','none')),life_months int CHECK(life_months>0),residual numeric(18,2) NOT NULL DEFAULT 0,effective_on date NOT NULL,simulation boolean NOT NULL DEFAULT true,UNIQUE(category_id,book,version));
CREATE TABLE depreciation_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),book text NOT NULL,period_start date NOT NULL,locked_at timestamptz,UNIQUE(book,period_start));
CREATE TABLE depreciation_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES assets(id),period_id uuid NOT NULL REFERENCES depreciation_periods(id),policy_id uuid NOT NULL REFERENCES depreciation_policies(id),amount numeric(18,2) NOT NULL,accumulated numeric(18,2) NOT NULL,book_value numeric(18,2) NOT NULL,UNIQUE(asset_id,period_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES users(id),event_key text NOT NULL,title text NOT NULL,body text NOT NULL,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(recipient_id,event_key));
CREATE TABLE email_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL REFERENCES notifications(id),attempts int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending',last_error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),UNIQUE(notification_id));
CREATE TABLE audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,changes jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
-- +goose Down
DROP TABLE sessions,email_deliveries,notifications,audit_log,depreciation_entries,depreciation_periods,depreciation_policies,asset_documents,document_versions,documents,work_orders,maintenance_plans,damage_reports,transfers,vehicle_renewals,vehicles,buildings,lands,assets,categories,locations,departments,business_units,users;
